const d = $input.first().json;

function durationMins(dur) {
  if (!dur) return 60;
  if (dur.includes('30')) return 30;
  if (dur.includes('45')) return 45;
  return 60;
}

const [h, m] = (d.interviewTime || '09:00').split(':').map(Number);
const endTotal = h * 60 + m + durationMins(d.duration);
const endH = String(Math.floor(endTotal / 60) % 24).padStart(2, '0');
const endM = String(endTotal % 60).padStart(2, '0');

const attendees = [];
if (d.candidateEmail) attendees.push({ email: d.candidateEmail });
if (d.ccEmails) {
  d.ccEmails.split(',').map(e => e.trim()).filter(Boolean).forEach(e => attendees.push({ email: e }));
}

return [{
  json: {
    summary: `Interview \u2013 ${d.candidateName || 'Candidate'} | ${d.role || 'Position'} @ Mervix Technology`,
    description: [
      d.role          ? `Position: ${d.role}` : '',
      d.interviewRound   ? `Round: ${d.interviewRound}` : '',
      d.interviewType    ? `Type: ${d.interviewType}` : '',
      d.interviewerName  ? `Interviewer: ${d.interviewerName}` : '',
      d.duration         ? `Duration: ${d.duration}` : '',
    ].filter(Boolean).join('\n'),
    startDateTime: `${d.interviewDate}T${d.interviewTime}:00`,
    endDateTime: `${d.interviewDate}T${endH}:${endM}:00`,
    timeZone: 'Asia/Kolkata',
    attendees,
  }
}];
